mapper.select:
SELECT count(*)
  FROM device
  JOIN thing_model ON thing_model.id = device.thing_model_id
                  AND thing_model.model_version = device.model_version
                  AND thing_model.status = 'PUBLISHED'
  JOIN thing_model_parameter binding ON binding.thing_model_id = thing_model.id
 WHERE device.id = #{deviceId}
   AND binding.parameter_id = #{parameterId}
   AND binding.unit_id = #{unitId}
